    while True:
        while text[pos].isspace()or text[pos]==',':pos+=1
        if text[pos]==']':break
        value,end=decoder.raw_decode(text,pos);out.append((value,text.count('\n',0,pos)+1,text.count('\n',0,end)+1));pos=end
    return out
